def is_balanced(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in '([{':
            stack.append(ch)               # push opener: O(1)
        elif ch in ')]}':
            if not stack or stack.pop() != pairs[ch]:  # top must match: O(1)
                return False
    return not stack                        # leftover openers => unbalanced

