class HashMap:
    def __init__(self, nbuckets=8):
        self.buckets = [[] for _ in range(nbuckets)]

    def _index(self, key):
        return hash(key) % len(self.buckets)      # hash -> bucket index

    def put(self, key, value):
        b = self.buckets[self._index(key)]
        for i, (k, _) in enumerate(b):
            if k == key:                           # update existing key
                b[i] = (key, value); return
        b.append((key, value))                     # new key -> append to chain

    def get(self, key):
        b = self.buckets[self._index(key)]
        for k, v in b:                             # scan only this bucket: O(chain)
            if k == key:
                return v
        raise KeyError(key)

