def dedup(xs):
    seen = set()               # average O(1) membership
    out = []
    for x in xs:
        if x not in seen:      # O(1) check instead of O(n) list scan
            seen.add(x)
            out.append(x)      # keep first-seen order (a set alone is unordered)
    return out

