        self.buckets = [[] for _ in range(nbuckets)]
        self.n = 0
        self.max_load = max_load

    def load_factor(self):
        return self.n / len(self.buckets)

    def _resize(self):
        old = [pair for b in self.buckets for pair in b]
        self.buckets = [[] for _ in range(len(self.buckets) * 2)]  # grow
        self.n = 0
        for k, v in old:            # rehash EVERY entry into the bigger table
            self.put(k, v)

