        b = self.buckets[hash(key) % len(self.buckets)]
        for i, (k, _) in enumerate(b):
            if k == key:
                b[i] = (key, value); return
        b.append((key, value)); self.n += 1
        if self.load_factor() > self.max_load:  # crossed threshold -> grow
            self._resize()

