        self.children = {}      # char -> TrieNode
        self.is_word = False    # True if a word ends at this node

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for ch in word:                     # O(L): one step per character
            node = node.children.setdefault(ch, TrieNode())
        node.is_word = True                 # mark the end of a complete word

    def _walk(self, prefix):
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return None                 # prefix path breaks -> not present
            node = node.children[ch]
        return node

    def contains(self, word):
        node = self._walk(word)
        return node is not None and node.is_word   # exact word needs the end flag

    def starts_with(self, prefix):
        return self._walk(prefix) is not None       # prefix just needs a path

