from collections import deque

def bfs(adj, start):
    visited = {start}                 # O(1) membership; prevents revisits + cycles
    order, dist = [], {start: 0}
    q = deque([start])                # FIFO queue -> level-by-level
    while q:
        u = q.popleft()               # oldest first (distance order)
        order.append(u)
        for v in sorted(adj[u]):
            if v not in visited:
                visited.add(v)
                dist[v] = dist[u] + 1 # shortest #edges from start (unweighted)
                q.append(v)
    return order, dist

def dfs(adj, start, visited=None, order=None):
    if visited is None: visited, order = set(), []
    visited.add(start); order.append(start)  # visit on discovery
    for v in sorted(adj[start]):
        if v not in visited:
            dfs(adj, v, visited, order)       # recurse deep (call stack)
    return order

